        list_for_each_entry_safe(buffer, tmp, &mapping->buffer_list, list) {
            if (buffer->release)
                buffer->release(buffer);
            list_del(&buffer->list);
            kfree(buffer);
        }
        spin_unlock(&mapping->queue_lock);
        kfree(mapping);
    }
}

void unmap_video_buffer(struct vm_area_struct *vma) {
    struct video_mapping *mapping = vma->vm_private_data;
    if (!mapping)
        return;

    if (atomic_dec_and_test(&mapping->ref_count)) {
        struct buffer *buf;
        int i;

        mutex_lock(&mapping->queue_lock);
        for (i = 0; i < mapping->queue_size; i++) {
            buf = &mapping->buffers[i];
            if (buf->ops && buf->ops->release)
                buf->ops->release(buf);
        }
        mutex_unlock(&mapping->queue_lock);

        kfree(mapping);
    }
}
